    fun lengthRollback() = check(listOf(
        Case("assignment: non-configurable index 1", program("var a=[];a[1]=7;a[2]=8;Object.defineProperty(a,\"1\",{configurable:false,enumerable:false});return run(a,function(){return a.length=0})"), "0|length=2/true;1=7/true/false/false"),
        Case("strict: non-configurable index 1", program("var a=[];a[1]=7;a[2]=8;Object.defineProperty(a,\"1\",{configurable:false,enumerable:false});return run(a,function(){\"use strict\";a.length=0;return true})"), "TypeError|length=2/true;1=7/true/false/false"),
        Case("define: non-configurable index 1", program("var a=[];a[1]=7;a[2]=8;Object.defineProperty(a,\"1\",{configurable:false,enumerable:false});return run(a,function(){return Object.defineProperty(a,\"length\",{value:0})})"), "TypeError|length=2/true;1=7/true/false/false"),
