    ))

    @Test
    fun lengthCoercion() = check(listOf(
        Case("ToUint32 then ToNumber [1.5, 1]", program("var a=[1,2,3],n=0,v={valueOf:function(){return [1.5, 1][n++]}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v})});return n+\"|\"+r"), "2|true|length=1/true;0=1/true/true/true"),
        Case("ToUint32 then ToNumber [1, 1.5]", program("var a=[1,2,3],n=0,v={valueOf:function(){return [1, 1.5][n++]}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v})});return n+\"|\"+r"), "2|RangeError|length=3/true;0=1/true/true/true;1=2/true/true/true;2=3/true/true/true"),
        Case("ToUint32 then ToNumber [2, 2]", program("var a=[1,2,3],n=0,v={valueOf:function(){return [2, 2][n++]}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v})});return n+\"|\"+r"), "2|true|length=2/true;0=1/true/true/true;1=2/true/true/true"),
        Case("ToUint32 then ToNumber [4294967296, 0]", program("var a=[1,2,3],n=0,v={valueOf:function(){return [4294967296, 0][n++]}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v})});return n+\"|\"+r"), "2|true|length=0/true"),
        Case("ToUint32 then ToNumber [0, 4294967296]", program("var a=[1,2,3],n=0,v={valueOf:function(){return [0, 4294967296][n++]}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v})});return n+\"|\"+r"), "2|RangeError|length=3/true;0=1/true/true/true;1=2/true/true/true;2=3/true/true/true"),
        Case("coercion side effect: Object.freeze(a)", program("var a=[1,2,3],n=0,v={valueOf:function(){if(n++===0){Object.freeze(a)}return 0}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v,writable:false})});return n+\"|\"+r"), "2|false|length=3/false;0=1/false/true/false;1=2/false/true/false;2=3/false/true/false"),
        Case("coercion side effect: Object.defineProperty(a,\"length\",{writable:false})", program("var a=[1,2,3],n=0,v={valueOf:function(){if(n++===0){Object.defineProperty(a,\"length\",{writable:false})}return 0}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v,writable:false})});return n+\"|\"+r"), "2|false|length=3/false;0=1/true/true/true;1=2/true/true/true;2=3/true/true/true"),
        Case("coercion side effect: Object.defineProperty(a,1,{configurable:false})", program("var a=[1,2,3],n=0,v={valueOf:function(){if(n++===0){Object.defineProperty(a,1,{configurable:false})}return 0}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v,writable:false})});return n+\"|\"+r"), "2|false|length=2/false;0=1/true/true/true;1=2/true/true/false"),
        Case("coercion side effect: a.length=1", program("var a=[1,2,3],n=0,v={valueOf:function(){if(n++===0){a.length=1}return 0}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v,writable:false})});return n+\"|\"+r"), "2|true|length=0/false"),
        Case("coercion side effect: a[4]=5", program("var a=[1,2,3],n=0,v={valueOf:function(){if(n++===0){a[4]=5}return 0}};var r=run(a,function(){return Reflect.defineProperty(a,\"length\",{value:v,writable:false})});return n+\"|\"+r"), "2|true|length=0/false"),
        Case("refused assignment does not coerce value", program("var a=[1,2],n=0;Object.defineProperty(a,\"length\",{writable:false});var v={valueOf:function(){n++;return 0}};return Reflect.set(a,\"length\",v)+\"|\"+n"), "false|0"),
        Case("refused definition does coerce value", program("var a=[1,2],n=0;Object.defineProperty(a,\"length\",{writable:false});var v={valueOf:function(){n++;return 0}};return Reflect.defineProperty(a,\"length\",{value:v})+\"|\"+n"), "false|2"),
        Case("second conversion exception identity", program("var a=[1,2],n=0,token={},v={valueOf:function(){if(n++===1)throw token;return 0}};try{a.length=v}catch(e){return (e===token)+\"|\"+n+\"|\"+snap(a)}"), "true|2|length=2/true;0=1/true/true/true;1=2/true/true/true"),
    ))

