        Case("frozen: unshift(4)", program("var a=[3,2,1];Object.freeze(a);return run(a,function(){return a.unshift(4)})"), "TypeError|length=3/false;0=3/false/true/false;1=2/false/true/false;2=1/false/true/false"),
