        Case("proxy Has/Get/Set/Delete order: copyWithin", program("var trace=\"\",a={0:1,2:3,length:3},p=new Proxy(a,{get:function(t,k){trace+=\"g\"+k+\";\";return Reflect.get(t,k)},has:function(t,k){trace+=\"h\"+k+\";\";return Reflect.has(t,k)},set:function(t,k,v){trace+=\"s\"+k+\";\";return Reflect.set(t,k,v)},deleteProperty:function(t,k){trace+=\"d\"+k+\";\";return Reflect.deleteProperty(t,k)}});Array.prototype.copyWithin.call(p,0,1);return trace+\"|\"+snap(a)"), "glength;h1;d0;h2;g2;s1;|length=3/true;1=3/true/true/true;2=3/true/true/true"),
