        Case("proxy delete refuses: copyWithin", program("var n=0,a=[1,,3],p=new Proxy(a,{deleteProperty:function(){n++;return false}});var r=run(a,function(){return Array.prototype.copyWithin.call(p,2,1)});return n+\"|\"+r"), "1|TypeError|length=3/true;0=1/true/true/true;2=3/true/true/true"),
