    @Test
    fun coercionAndSpecies() = check(listOf(
        Case("splice frozen species result: splice(0,1)", program("var a=[1,2,3];a.constructor={[Symbol.species]:function(){return Object.freeze([])}};return run(a,function(){return a.splice(0,1)})"), "TypeError|length=3/true;0=1/true/true/true;1=2/true/true/true;2=3/true/true/true"),
        Case("splice frozen species result: splice()", program("var a=[1,2,3];a.constructor={[Symbol.species]:function(){return Object.freeze([])}};return run(a,function(){return a.splice()})"), "TypeError|length=3/true;0=1/true/true/true;1=2/true/true/true;2=3/true/true/true"),
        Case("splice frozen species result: splice(1,0)", program("var a=[1,2,3];a.constructor={[Symbol.species]:function(){return Object.freeze([])}};return run(a,function(){return a.splice(1,0)})"), "TypeError|length=3/true;0=1/true/true/true;1=2/true/true/true;2=3/true/true/true"),
        Case("splice frozen species result: splice(0,2)", program("var a=[1,2,3];a.constructor={[Symbol.species]:function(){return Object.freeze([])}};return run(a,function(){return a.splice(0,2)})"), "TypeError|length=3/true;0=1/true/true/true;1=2/true/true/true;2=3/true/true/true"),
        Case("species receives deletion length", program("var a=[1,2,3],n=-1;a.constructor={[Symbol.species]:function(len){n=len;return []}};a.splice(0,2);return n"), "2"),
        Case("splice argument coercion precedes constructor read", program("var a=[1,2,3],trace=\"\";Object.defineProperty(a,\"constructor\",{get:function(){trace+=\"ctor;\";return {[Symbol.species]:function(n){trace+=\"species\"+n+\";\";return []}}}});a.splice({valueOf:function(){trace+=\"start;\";return 0}},{valueOf:function(){trace+=\"count;\";return 1}});return trace"), "start;count;ctor;species1;"),
        Case("splice start coercion: Object.freeze(a)", program("var a=[1,2,3];return run(a,function(){return a.splice({valueOf:function(){Object.freeze(a);return 0}},1,9)})"), "TypeError|length=3/false;0=1/false/true/false;1=2/false/true/false;2=3/false/true/false"),
        Case("copyWithin start coercion: Object.freeze(a)", program("var a=[1,2,3];return run(a,function(){return a.copyWithin(0,{valueOf:function(){Object.freeze(a);return 1}})})"), "TypeError|length=3/false;0=1/false/true/false;1=2/false/true/false;2=3/false/true/false"),
        Case("splice start coercion: a.length=0", program("var a=[1,2,3];return run(a,function(){return a.splice({valueOf:function(){a.length=0;return 0}},1,9)})"), "|length=3/true;0=9/true/true/true"),
        Case("copyWithin start coercion: a.length=0", program("var a=[1,2,3];return run(a,function(){return a.copyWithin(0,{valueOf:function(){a.length=0;return 1}})})"), "same|length=0/true"),
        Case("splice start coercion: a.length=1", program("var a=[1,2,3];return run(a,function(){return a.splice({valueOf:function(){a.length=1;return 0}},1,9)})"), "1|length=3/true;0=9/true/true/true"),
        Case("copyWithin start coercion: a.length=1", program("var a=[1,2,3];return run(a,function(){return a.copyWithin(0,{valueOf:function(){a.length=1;return 1}})})"), "same|length=1/true"),
        Case("splice start coercion: Object.defineProperty(a,1,{writable:false})", program("var a=[1,2,3];return run(a,function(){return a.splice({valueOf:function(){Object.defineProperty(a,1,{writable:false});return 0}},1,9)})"), "1|length=3/true;0=9/true/true/true;1=2/false/true/true;2=3/true/true/true"),
        Case("copyWithin start coercion: Object.defineProperty(a,1,{writable:false})", program("var a=[1,2,3];return run(a,function(){return a.copyWithin(0,{valueOf:function(){Object.defineProperty(a,1,{writable:false});return 1}})})"), "TypeError|length=3/true;0=2/true/true/true;1=2/false/true/true;2=3/true/true/true"),
        Case("species construction freezes input", program("var a=[1,2,3];a.constructor={[Symbol.species]:function(){Object.freeze(a);return []}};return run(a,function(){return a.splice(0,1)})"), "TypeError|length=3/false;0=1/false/true/false;1=2/false/true/false;2=3/false/true/false"),
        Case("splice species define trap refuses", program("var n=0,a=[1,2];a.constructor={[Symbol.species]:function(){return new Proxy({},{defineProperty:function(){n++;return false}})}};var r=run(a,function(){return a.splice(0,1)});return n+\"|\"+r"), "1|TypeError|length=2/true;0=1/true/true/true;1=2/true/true/true"),
        Case("empty splice still sets species result length", program("var n=0,a=[1,2];a.constructor={[Symbol.species]:function(){return new Proxy({},{set:function(t,k,v){n++;return false}})}};var r=run(a,function(){return a.splice()});return n+\"|\"+r"), "1|TypeError|length=2/true;0=1/true/true/true;1=2/true/true/true"),
        Case("proxy array uses species", program("var n=0,a=[1,2];a.constructor={[Symbol.species]:function(k){n=k;return []}};Array.prototype.splice.call(new Proxy(a,{}),0,1);return n"), "1"),
        Case("species may return input array", program("var a=[1,2,3];a.constructor={[Symbol.species]:function(){return a}};return run(a,function(){return a.splice(1,1,9)})"), "same|length=3/true;0=2/true/true/true;1=9/true/true/true"),
        Case("species own non-configurable element refuses definition", program("var a=[1,2],r=[];Object.defineProperty(r,0,{value:7,configurable:false});a.constructor={[Symbol.species]:function(){return r}};var outcome=run(a,function(){return a.splice(0,1)});return outcome+\"|\"+snap(r)"), "TypeError|length=2/true;0=1/true/true/true;1=2/true/true/true|length=1/true;0=7/false/false/false"),
        Case("copy frozen input: toReversed()", program("var a=Object.freeze([3,2,1]);return a.toReversed().join()+\"|\"+snap(a)"), "1,2,3|length=3/false;0=3/false/true/false;1=2/false/true/false;2=1/false/true/false"),
        Case("copy defines own elements: toReversed()", program("var a=[3,2,1],n=0;Object.defineProperty(Array.prototype,0,{set:function(){n++},configurable:true});var r=a.toReversed();return n+\"|\"+snap(r)"), "0|length=3/true;0=1/true/true/true;1=2/true/true/true;2=3/true/true/true"),
        Case("copy frozen input: toSorted()", program("var a=Object.freeze([3,2,1]);return a.toSorted().join()+\"|\"+snap(a)"), "1,2,3|length=3/false;0=3/false/true/false;1=2/false/true/false;2=1/false/true/false"),
        Case("copy defines own elements: toSorted()", program("var a=[3,2,1],n=0;Object.defineProperty(Array.prototype,0,{set:function(){n++},configurable:true});var r=a.toSorted();return n+\"|\"+snap(r)"), "0|length=3/true;0=1/true/true/true;1=2/true/true/true;2=3/true/true/true"),
        Case("copy frozen input: toSpliced(1,1,4)", program("var a=Object.freeze([3,2,1]);return a.toSpliced(1,1,4).join()+\"|\"+snap(a)"), "3,4,1|length=3/false;0=3/false/true/false;1=2/false/true/false;2=1/false/true/false"),
        Case("copy defines own elements: toSpliced(1,1,4)", program("var a=[3,2,1],n=0;Object.defineProperty(Array.prototype,0,{set:function(){n++},configurable:true});var r=a.toSpliced(1,1,4);return n+\"|\"+snap(r)"), "0|length=3/true;0=3/true/true/true;1=4/true/true/true;2=1/true/true/true"),
        Case("copy frozen input: with(1,4)", program("var a=Object.freeze([3,2,1]);return a.with(1,4).join()+\"|\"+snap(a)"), "3,4,1|length=3/false;0=3/false/true/false;1=2/false/true/false;2=1/false/true/false"),
        Case("copy defines own elements: with(1,4)", program("var a=[3,2,1],n=0;Object.defineProperty(Array.prototype,0,{set:function(){n++},configurable:true});var r=a.with(1,4);return n+\"|\"+snap(r)"), "0|length=3/true;0=3/true/true/true;1=4/true/true/true;2=1/true/true/true"),
    ))

    private fun program(body: String): String = "(function(){" + helpers + body + "})()"
    private val helpers = "function snap(a){var d=Object.getOwnPropertyDescriptor(a,\"length\"),s=\"length=\"+a.length+\"/\"+d.writable;var keys=Object.getOwnPropertyNames(a);keys.sort(function(x,y){return Number(x)-Number(y)});for(var i=0;i<keys.length;i++){var k=keys[i];if(String(k>>>0)!==k||k===\"4294967295\")continue;var p=Object.getOwnPropertyDescriptor(a,k);s+=\";\"+k+\"=\"+(\"value\" in p?String(p.value):\"accessor\")+\"/\"+p.writable+\"/\"+p.enumerable+\"/\"+p.configurable}return s}function run(a,f){var r;try{var v=f();r=v===a?\"same\":String(v)}catch(e){r=e.name||String(e)}return r+\"|\"+snap(a)}"
}
